arguments.command:
true_cmd=$(cat << 'EOF_TRUE'
<||then_command||>
EOF_TRUE
) && false_cmd=$(cat << 'EOF_FALSE'
<||else_command||>
EOF_FALSE
) && cond=$(cat << 'EOF_COND'
<||condition||>
EOF_COND
) && true_cmd="${true_cmd//,/;}" && false_cmd="${false_cmd//,/;}" && if printf "%s" "$cond" | termy -y >/dev/null 2>&1; then printf "%s" "$true_cmd" | termy -y; else if [ -n "$false_cmd" ]; then printf "%s" "$false_cmd" | termy -y; fi; fi
